import axios from "axios";

const { PAYMENTS_API_URL, PAYMENTS_KEY } = process.env;
const missing = [
  !PAYMENTS_API_URL && "PAYMENTS_API_URL",
  !PAYMENTS_KEY && "PAYMENTS_KEY",
].filter(Boolean);
if (missing.length) {
  console.error(`sync failed: missing required env var(s): ${missing.join(", ")}`);
  process.exit(1);
}

const api = axios.create({
  baseURL: PAYMENTS_API_URL,
  headers: { Authorization: `Bearer ${PAYMENTS_KEY}` },
});

try {
  const res = await api.post("/v1/charges/sync", {});
  console.log("synced", res.data);
} catch (err) {
  console.error("sync failed:", err.message);
  process.exit(1);
}

